import{_ as e,o,c as l,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"动作菜单与即时预览","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/actions-and-preview.md","filePath":"zh-CN/user-guide/actions-and-preview.md","lastUpdated":1788410889000}'),a={name:"zh-CN/user-guide/actions-and-preview.md"};function n(i,t,s,d,g,c){return o(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="动作菜单与即时预览" tabindex="-1">动作菜单与即时预览 <a class="header-anchor" href="#动作菜单与即时预览" aria-label="Permalink to &quot;动作菜单与即时预览&quot;">​</a></h1><p>Lertaro 不仅能极速定位文件，更集成了完善的上下文操作体系与强大的即时预览面板，让你无需频繁打开文件资源管理器即可完成文件的查看、管理与分发。</p><h2 id="_1-动作菜单详解" tabindex="-1">1. 动作菜单详解 <a class="header-anchor" href="#_1-动作菜单详解" aria-label="Permalink to &quot;1. 动作菜单详解&quot;">​</a></h2><p>在任意搜索结果（文件、文件夹、应用程序或插件条目）上按下 <code>Ctrl+O</code> 或按方向键 <code>→</code>，即可展开该项目的上下文动作菜单。在完整搜索窗口中，右键点击结果也会为该项目打开相同的动作菜单。</p><h3 id="内置核心动作速查" tabindex="-1">内置核心动作速查 <a class="header-anchor" href="#内置核心动作速查" aria-label="Permalink to &quot;内置核心动作速查&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">动作名称</th><th style="text-align:left;">默认快捷键</th><th style="text-align:left;">功能说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>打开</strong></td><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">使用系统默认关联程序打开选中的文件或启动应用程序。</td></tr><tr><td style="text-align:left;"><strong>在资源管理器中定位</strong></td><td style="text-align:left;"><code>Ctrl+Enter</code></td><td style="text-align:left;">打开文件所在目录，并在资源管理器中直接选中该文件。</td></tr><tr><td style="text-align:left;"><strong>以管理员身份运行</strong></td><td style="text-align:left;"><code>Ctrl+Shift+Enter</code></td><td style="text-align:left;">以管理员权限启动选中的程序（支持可执行文件、快捷方式、批处理脚本等）。</td></tr><tr><td style="text-align:left;"><strong>复制完整路径</strong></td><td style="text-align:left;"><code>Ctrl+Shift+C</code></td><td style="text-align:left;">将文件的绝对路径（如 <code>D:\\Projects\\app.exe</code>）复制到剪贴板。</td></tr><tr><td style="text-align:left;"><strong>剪切 / 复制文件</strong></td><td style="text-align:left;"><code>Ctrl+X</code> / <code>Ctrl+C</code></td><td style="text-align:left;">将文件本身放入剪贴板，可直接在资源管理器或其他目录中粘贴。</td></tr><tr><td style="text-align:left;"><strong>粘贴到此处</strong></td><td style="text-align:left;"><code>Ctrl+V</code></td><td style="text-align:left;">当选中目标为文件夹时，将剪贴板中的文件直接粘贴至该目录下。</td></tr><tr><td style="text-align:left;"><strong>删除（移入回收站）</strong></td><td style="text-align:left;"><code>Delete</code></td><td style="text-align:left;">将选中的文件或文件夹安全移至 Windows 回收站。</td></tr><tr><td style="text-align:left;"><strong>彻底删除</strong></td><td style="text-align:left;"><code>Shift+Delete</code></td><td style="text-align:left;">永久删除选中的文件或文件夹（不可从回收站恢复，会弹出二次确认）。</td></tr><tr><td style="text-align:left;"><strong>打开 Windows 右键菜单</strong></td><td style="text-align:left;">—</td><td style="text-align:left;">展开原生的 Windows 资源管理器完整上下文菜单（包含第三方软件扩展和发送到子菜单）。</td></tr></tbody></table><h3 id="动作菜单交互与即时过滤" tabindex="-1">动作菜单交互与即时过滤 <a class="header-anchor" href="#动作菜单交互与即时过滤" aria-label="Permalink to &quot;动作菜单交互与即时过滤&quot;">​</a></h3><ul><li><strong>即输即过滤</strong>：展开动作菜单后，直接打字即可按动作名称快速过滤（例如输入 <code>copy</code> 即刻定位到所有复制相关操作）。</li><li><strong>独立搜索框</strong>：动作菜单拥有独立且打开后自动获得焦点的搜索框，过滤动作不会改变主搜索词。切换菜单层级时会清空动作过滤词，并让新层级的搜索框获得焦点。</li><li><strong>浮动动作面板</strong>：快速窗口、快速启动面板和完整搜索窗口中的动作都会以悬浮面板显示，并锚定在当前项目附近。快速启动面板会临时扩展到动作列表的完整工作高度，关闭动作菜单后恢复紧凑高度。</li><li><strong>层级导航</strong>：在带有子菜单的条目（如“发送到”或级联动作）上按下 <code>→</code> 或 <code>Enter</code> 进入下一级；按 <code>←</code> 或在过滤词为空时按 <code>Backspace</code> 返回上一级。在嵌套菜单中按 <code>Escape</code> 或点击鼠标右键会返回上一级；在根层级则关闭动作菜单。</li><li><strong>点击空白处关闭</strong>：点击浮动动作面板之外的区域会关闭面板。宿主支持时，在动作面板打开期间右键点击其他结果会就地替换当前动作目标。</li><li><strong>动作快捷键</strong>：动作面板获得焦点后即可使用提供器定义的动作快捷键。执行后会关闭浮动面板，但完整搜索窗口或快速启动面板仍保持打开。</li></ul><h2 id="_2-完整搜索窗口的结果列表交互" tabindex="-1">2. 完整搜索窗口的结果列表交互 <a class="header-anchor" href="#_2-完整搜索窗口的结果列表交互" aria-label="Permalink to &quot;2. 完整搜索窗口的结果列表交互&quot;">​</a></h2><p>主搜索窗口（<code>Ctrl+F</code>）专为海量文件管理与多维度浏览设计：</p><ul><li><strong>双击路径列定位</strong>：双击结果列表中的<strong>文件名称</strong>为直接打开文件；双击<strong>路径</strong>列则会自动打开该文件所在的父级文件夹。</li><li><strong>无限流式结果加载</strong>：在搜索大容量磁盘或数百万条目时，结果会随后台索引引擎的检索实时流式呈现在列表中，无需等待全盘扫描完毕即可随时点击或选中操作。</li><li><strong>键盘循环导航</strong>：在结果第一行按 <code>↑</code> 可直接跳转到末尾行，在最后一行按 <code>↓</code> 可回到首行。</li><li><strong>选择数量摘要</strong>：选中多个结果时，状态栏会在结果总数旁显示当前选中的项目数量。</li><li><strong>窗口无边框拖拽与尺寸记忆</strong>：主窗口顶部非输入区域可作为拖拽抓取条，鼠标指针悬停时会有提示条淡入；手动调整的窗口宽高会自动记忆并在下次启动时沿用。</li></ul><h2 id="_3-quicklook-即时预览机制" tabindex="-1">3. QuickLook 即时预览机制 <a class="header-anchor" href="#_3-quicklook-即时预览机制" aria-label="Permalink to &quot;3. QuickLook 即时预览机制&quot;">​</a></h2><p>在任意搜索结果上按下 <code>Alt+P</code>，即可在搜索窗口旁呼出一个功能强大的即时预览面板，支持丰富的文件类型：</p><h3 id="多格式预览支持" tabindex="-1">多格式预览支持 <a class="header-anchor" href="#多格式预览支持" aria-label="Permalink to &quot;多格式预览支持&quot;">​</a></h3><ul><li><strong>图片与矢量图</strong>：支持 JPG、PNG、GIF（动图自动播放）、BMP、WebP、ICO、SVG 等常见图像格式的高清缩放呈现。</li><li><strong>文档与文本代码</strong>：支持 TXT、Markdown、JSON、XML、YAML、C#、Python、JS、HTML 等代码与文本的高亮排版呈现。</li><li><strong>音视频即时播放</strong>：MP4、MKV、AVI、MOV、WMV、MP3、WAV、FLAC、WMA 等媒体文件在预览面板打开时会<strong>自动开始播放</strong>，并配备自适应主题的迷你控制条（播放/暂停、拖动进度、实时时长、静音控制），切换选中项时立即停止。</li><li><strong>文件夹结构透视</strong>：选中文件夹时，预览面板会自动列出其前 30 个直接子项目并显示文件图标与大小，自动过滤系统和隐藏文件。</li></ul><h3 id="细节设计与避让机制" tabindex="-1">细节设计与避让机制 <a class="header-anchor" href="#细节设计与避让机制" aria-label="Permalink to &quot;细节设计与避让机制&quot;">​</a></h3><ul><li><strong>尺寸与边界自适应</strong>：预览窗口的尺寸可在<a href="./settings/general.html#预览窗口"><strong>设置 → 通用 → 预览窗口</strong></a>中自定义，系统会自动确保预览窗口不会超出当前显示器的可视工作区。</li><li><strong>原生弹窗自动避让</strong>：当预览 Office 加密文档弹出输入密码对话框时，Lertaro 会自动临时隐藏快速窗口与预览面板，待密码输入完成或弹窗关闭后自动无缝恢复。</li><li><strong>预览窗口拖拽源</strong>：预览面板顶部可作为拖拽源，直接将正在预览的文件拖入编辑器、浏览器或外部聊天软件中。</li></ul><h2 id="_4-插件交互式与富文本预览" tabindex="-1">4. 插件交互式与富文本预览 <a class="header-anchor" href="#_4-插件交互式与富文本预览" aria-label="Permalink to &quot;4. 插件交互式与富文本预览&quot;">​</a></h2><p>QuickLook 不仅支持本地文件预览，更开放了强大的插件交互扩展能力：</p><ul><li><strong>自适应深浅色富文本</strong>：基于现代化 WebView2 与原生组件渲染，自动适配系统的深色/浅色主题，并注入清晰的高对比度字体与精致的半透明细滚动条。</li><li><strong>丰富的插件卡片</strong>：支持词典释义卡片、即时天气、网页即时快照、API 调试信息等复杂交互式面板。</li></ul><h2 id="_5-第三方独立-quicklook-桥接-可选" tabindex="-1">5. 第三方独立 QuickLook 桥接（可选） <a class="header-anchor" href="#_5-第三方独立-quicklook-桥接-可选" aria-label="Permalink to &quot;5. 第三方独立 QuickLook 桥接（可选）&quot;">​</a></h2><p>如果你已在系统中安装了独立的第三方开源工具 <strong>QuickLook</strong>（<a href="https://github.com/QL-Win/QuickLook" target="_blank" rel="noreferrer">GitHub 上的 QL-Win/QuickLook</a>），可以在<a href="./settings/plugins.html"><strong>设置 → 插件</strong></a>中启用内置的 <strong>QuickLook 桥接</strong> 插件。</p><ul><li><strong>接管预览</strong>：该插件会通过本地命名管道连接独立的 QuickLook 进程，并将外部预览窗口自动吸附在 Lertaro 旁。</li><li><strong>无缝回退</strong>：若第三方 QuickLook 进程未运行或已关闭，Lertaro 会自动平滑回退至内置的原生预览面板，确保预览体验始终可用。</li></ul><h2 id="_6-解除文件占用" tabindex="-1">6. 解除文件占用 <a class="header-anchor" href="#_6-解除文件占用" aria-label="Permalink to &quot;6. 解除文件占用&quot;">​</a></h2><p>官方的<strong>文件占用解除</strong>插件为已存在的文件提供单选动作。它会列出当前正在使用该文件的进程、PID 和可执行文件路径，并请求这些进程释放文件。选择文件夹、文件不存在或同时选择多个项目时，该动作不可用；未检测到占用进程时，请求释放按钮也会禁用。窗口使用宿主主题，并在对话框模式下保持在搜索窗口上方且不出现在 Alt+Tab 切换列表中，同时提供刷新功能。</p><h2 id="_7-添加到收藏夹" tabindex="-1">7. 添加到收藏夹 <a class="header-anchor" href="#_7-添加到收藏夹" aria-label="Permalink to &quot;7. 添加到收藏夹&quot;">​</a></h2><p>CoreExtensions 提供<strong>添加到收藏夹</strong>动作，适用于单个已存在的文件或文件夹。该动作会打开主题化对话框让你填写显示名称；如果相同路径已经是收藏项，动作会隐藏。</p>',27)])])}const f=e(a,[["render",n]]);export{u as __pageData,f as default};
